<script lang="ts">
 import {onDestroy} from 'svelte';import {catalogApi} from '$lib/api/catalog';import {abilities,tableAtLevel,type CharacterBuild,type CatalogSpell} from '$lib/rules/characterBuilder';import {getAbilityModifier,getProficiencyBonus,type AbilityScores} from '$lib/types';
 export let build:CharacterBuild;export let level=1;export let abilityScores:AbilityScores;export let editable=true;
 const abilityNames={strength:'Fuerza',dexterity:'Destreza',constitution:'Constitución',intelligence:'Inteligencia',wisdom:'Sabiduría',charisma:'Carisma'};
 let query='';let spellLevel=-1;let onlyClass=true;let rows:Array<{key:string;name:string;level?:number;school?:string;sourceKey:string;sourceLabel?:string;status?:string;contentMode?:string}>=[];let loading=false;let error='';let detail:CatalogSpell|null=null;let timer:ReturnType<typeof setTimeout>;let generation=0;let custom=false;let customName='';let customDesc='';let customLevel=0;
 $: modifier=build.castingAbility==='none'?null:getAbilityModifier(abilityScores[build.castingAbility]);
 $: schedule(query,spellLevel,build.edition,onlyClass?build.class.key:'',build.scope,editable);
 function schedule(q:string,l:number,e:string,c:string,s:string,visible:boolean){clearTimeout(timer);const id=++generation;if(!visible)return;timer=setTimeout(async()=>{loading=true;error='';try{const found=await catalogApi.searchSpells(q,e,l,c,s);if(id===generation)rows=found;}catch{if(id===generation)error='No se pudo cargar el catálogo de hechizos.';}finally{if(id===generation)loading=false;}},180);}
 async function preview(key:string){error='';loading=true;try{detail=await catalogApi.getSpell(key);}catch{error='No se pudo cargar el hechizo. Reintentá.';}finally{loading=false;}}
 function add(){if(!detail||build.spells.some(s=>s.key===detail?.slug))return;build.spells=[...build.spells,{key:detail.slug,name:detail.name,level:detail.level,prepared:detail.level===0,desc:''}];build=build;}
 async function fillSlots(){error='';if(!build.class.key)return;try{const option=await catalogApi.getOption(build.class.key);const rows=tableAtLevel(option,level);build.slots=Array(9).fill(0);for(const feature of option.features.filter(v=>v.type==='SPELL_SLOTS')){const n=Number(/^[1-9]/.exec(feature.name)?.[0]);const value=Number(feature.table.find(v=>v.level===level)?.column_value);if(n&&Number.isInteger(value))build.slots[n-1]=value;}
 build.pactSlots=Number(rows.find(v=>v.name==='Spell Slots')?.value)||0;build.pactLevel=Number.parseInt(rows.find(v=>v.name==='Slot Level')?.value||'0')||0;build=build;}catch{error='No se pudo cargar la progresión de espacios.';}}
 function addCustom(){if(!customName.trim()||build.spells.length>=200)return;build.spells=[...build.spells,{key:'',name:customName.trim(),level:customLevel,prepared:customLevel===0,desc:customDesc}];customName='';customDesc='';custom=false;}
 onDestroy(()=>{clearTimeout(timer);generation++;});
</script>
<section class="space-y-3">
 <h4 class="font-medieval font-bold text-lg">📖 Libro de hechizos</h4>
 {#if editable}<label class="block text-sm">Característica de lanzamiento<select class="select select-bordered select-sm w-full" bind:value={build.castingAbility}><option value="none">Sin lanzamiento</option>{#each abilities as ability}<option value={ability}>{abilityNames[ability]}</option>{/each}</select></label>{/if}
 {#if modifier!==null}<p class="text-sm font-bold">CD de salvación: {8+getProficiencyBonus(level)+modifier} · Ataque mágico: {getProficiencyBonus(level)+modifier>=0?'+':''}{getProficiencyBonus(level)+modifier}</p>{/if}
 <details class="border border-primary/30 rounded p-2"><summary class="cursor-pointer text-sm font-semibold">Espacios de conjuro máximos</summary>
 {#if editable}<button type="button" class="btn btn-xs my-2" on:click={fillSlots} disabled={!build.class.key}>Aplicar tabla de clase para nivel {level}</button><p class="text-xs mb-2">Revisá la tabla de la clase. Los espacios de pacto se guardan aparte; los lanzamientos gratuitos se anotan en Rasgos.</p>{/if}
 <div class="grid grid-cols-3 gap-2">{#each build.slots as count,i}<label class="text-xs">Nivel {i+1}{#if editable}<input aria-label={`Espacios nivel ${i+1}`} type="number" min="0" max="20" class="input input-bordered input-sm w-full" bind:value={build.slots[i]}/>{:else}<span class="block font-bold">{count}</span>{/if}</label>{/each}</div>
 <div class="grid grid-cols-2 gap-2 mt-2"><label class="text-xs">Espacios de pacto<input disabled={!editable} class="input input-bordered input-sm w-full" type="number" min="0" max="20" bind:value={build.pactSlots}/></label><label class="text-xs">Nivel de pacto<input disabled={!editable} class="input input-bordered input-sm w-full" type="number" min="0" max="9" bind:value={build.pactLevel}/></label></div>
 </details>
 {#if editable}
  <div class="space-y-2 border border-primary/30 p-2 rounded">
   <input aria-label="Buscar hechizos" class="input input-bordered input-sm w-full" bind:value={query} placeholder="Buscar hechizos por nombre en inglés…"/>
   <div class="flex items-center gap-2"><select aria-label="Nivel de hechizo" class="select select-bordered select-sm flex-1 min-w-0" bind:value={spellLevel}><option value={-1}>Todos los niveles</option><option value={0}>Trucos</option>{#each Array(9) as _,i}<option value={i+1}>Nivel {i+1}</option>{/each}</select><label class="text-xs flex gap-1 items-center"><input type="checkbox" class="checkbox checkbox-xs" bind:checked={onlyClass}/>Solo mi clase</label></div>
   <p class="text-xs">Si el catálogo no tiene lista para tu clase o el hechizo viene de una dote o especie, desmarcá «Solo mi clase».</p>
   {#if loading}<p class="text-xs" role="status">Cargando…</p>{/if}
   <div class="max-h-48 overflow-y-auto space-y-1">{#each rows as row}<button type="button" class="w-full text-left border border-primary/20 p-2 rounded text-sm" on:click={()=>preview(row.key)}>{row.name}<span class="block text-xs opacity-70">{row.level===0?'Truco':`Nivel ${row.level}`} · {row.school} · {row.sourceLabel||row.sourceKey}{row.contentMode==='open-text'?'':' · Datos mecánicos'}</span></button>{/each}</div>
   {#if !loading&&!rows.length}<p class="text-xs">Sin coincidencias para estos filtros.</p>{/if}
  </div>
  <button type="button" class="btn btn-sm btn-outline text-neutral" on:click={()=>custom=!custom}>Hechizo personalizado</button>
  {#if custom}<div class="space-y-2"><input aria-label="Nombre del hechizo personalizado" class="input input-bordered input-sm w-full" bind:value={customName} maxlength="100" placeholder="Nombre"/><input aria-label="Nivel del hechizo personalizado" type="number" min="0" max="9" bind:value={customLevel} class="input input-bordered input-sm w-full"/><textarea aria-label="Reglas del hechizo personalizado" class="textarea textarea-bordered w-full" bind:value={customDesc} maxlength="4000" placeholder="Efecto, componentes, alcance y duración"/><button type="button" class="btn btn-sm" disabled={!customName.trim()} on:click={addCustom}>Agregar personalizado</button></div>{/if}
 {/if}
 {#if error}<p class="text-error text-sm" role="alert">{error}</p>{/if}
 {#if detail}<div class="rounded border border-primary/40 p-3 space-y-2"><div class="flex justify-between gap-2"><h5 class="font-bold">{detail.name}</h5><button aria-label="Cerrar detalle del hechizo" type="button" on:click={()=>detail=null}>✕</button></div><a class="link text-xs" href={`/sources#${detail.catalogSource.key}`} target="_blank" rel="noreferrer">{detail.catalogSource.name} · {detail.catalogSource.edition}</a><p class="text-xs">{detail.school} · {detail.castingTime} · {detail.range} · {detail.duration}<br/>{detail.components}{detail.concentration?' · Concentración':''}{detail.ritual?' · Ritual':''}</p><p class="text-sm whitespace-pre-wrap break-words">{detail.desc}</p>{#if detail.contentMode}<p class="text-xs">Ficha de datos mecánicos. Consultá en la publicación las reglas completas, el efecto y los componentes materiales.</p>{/if}{#each detail.references||[] as ref}<a class="link text-xs block" href={ref.url} target="_blank" rel="noreferrer">Ver referencia de {ref.provider}{ref.page?` · página ${ref.page}`:''}</a>{/each}{#if detail.higherLevel}<p class="text-sm whitespace-pre-wrap">{detail.higherLevel}</p>{/if}{#if editable}<button type="button" class="btn btn-sm" disabled={build.spells.length>=200||build.spells.some(s=>s.key===detail?.slug)} on:click={add}>Agregar al libro</button>{/if}</div>{/if}
 {#if build.spells.some(s=>s.level>Math.max(build.pactLevel,...build.slots.map((n,i)=>n?i+1:0)))}<p class="text-xs">Hay hechizos en el libro de un nivel superior a tus espacios actuales. Revisá cuáles podés preparar o lanzar y los usos gratuitos de tus rasgos.</p>{/if}
 <p class="text-xs">{build.spells.length} en el libro · {build.spells.filter(s=>s.prepared&&s.level>0).length} preparados · {build.spells.filter(s=>s.level===0).length} trucos</p>
 {#each build.spells as spell,i}<div class="border-t border-primary/20 py-2"><div class="flex gap-2 items-center"><button type="button" class="text-left flex-1 text-sm font-semibold" on:click={()=>spell.key?preview(spell.key):undefined}>{spell.name} · {spell.level===0?'Truco':`N${spell.level}`}</button>{#if editable}<label class="flex items-center gap-1 text-xs"><input type="checkbox" class="checkbox checkbox-xs" bind:checked={spell.prepared}/>Preparado</label><button type="button" aria-label={`Quitar ${spell.name}`} on:click={()=>build.spells=build.spells.filter((_,index)=>index!==i)}>✕</button>{:else}<span class="badge badge-sm">{spell.prepared?'Preparado':'En el libro'}</span>{/if}</div>{#if !spell.key}<p class="whitespace-pre-wrap break-words text-sm">{spell.desc}</p>{/if}</div>{/each}
</section>
<style>
 .input, .select, .textarea { color: #f7ecd8; background-color: #2d241c; }
</style>
